import {useEffect,useState} from 'react';
import {createRoot} from 'react-dom/client';
import ForumView from '../../../../src/components/dzmm/forum-view';
import type {DzmmForumAuthor,DzmmForumPost,DzmmForumReply} from '../../../../src/lib/dzmm-forum-types';
import '../../src/page.css';
const account='77777777-7777-4777-8777-777777777777', postId='cccccccc-cccc-4ccc-8ccc-cccccccccccc';
const normal:DzmmForumAuthor={id:account,nickname:'本地普通体验者'};
const demo:DzmmForumAuthor={id:'88888888-8888-4888-8888-888888888888',nickname:'窗灯拾页',isDemo:true,provenance:{kind:'fictional-demo',source:'original',label:'官方原创示例',batchId:'forum-seed-fixture'}};
const now=Date.now();
const posts:DzmmForumPost[]=[{id:postId,title:'创作练习：把旧票留在上一幕',body:'一张车票可以推动故事，也可以在旅途结束后放进抽屉。这里是一段原创讨论样本：当角色换了地点，哪些细节该退场？',category:'characters',tags:['剧情连续性','创作练习'],author:demo,createdAt:now,updatedAt:now,upvotes:0,downvotes:0,myVote:0,replyCount:2},{id:'dddddddd-dddd-4ddd-8ddd-dddddddddddd',title:'普通主题：周末的读书计划',body:'本地普通用户主题，不应显示演示角色来源。',category:'life',tags:['阅读'],author:normal,createdAt:now-1000,updatedAt:now-1000,upvotes:0,downvotes:0,myVote:0,replyCount:0}];
const replies:DzmmForumReply[]=[{id:'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',postId,body:'可以给物品补一个明确结局：到家后把票收进抽屉，后续只在回忆这段旅途时再提。',author:demo,createdAt:now},{id:'ffffffff-ffff-4fff-8fff-ffffffffffff',postId,body:'这是普通用户回复，不继承主题的演示标记。',author:normal,createdAt:now+1}];
function response(body:unknown,status=200){return new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json'}})}
window.fetch=async(input,init)=>{const url=new URL(input instanceof Request?input.url:String(input),location.origin);const method=(init?.method??(input instanceof Request?input.method:'GET')).toUpperCase();if(url.origin!==location.origin)return response({error:'隔离验收阻止外部请求'},501);const base='/api/backend/v1/forum';if(url.pathname===`${base}/posts`&&method==='GET'){const category=url.searchParams.get('category'),q=url.searchParams.get('q');const items=posts.filter(p=>(!category||p.category===category)&&(!q||`${p.title}${p.body}`.includes(q)));return response({posts:items,total:items.length,offset:0,limit:20,hasMore:false,nextCursor:null,popularTags:[]})}if(url.pathname===`${base}/posts/${postId}`&&method==='GET')return response({post:posts[0],replies,total:replies.length,offset:0,limit:20,hasMore:false,nextCursor:null});if(url.pathname===`${base}/posts/${posts[1].id}`&&method==='GET')return response({post:posts[1],replies:[],total:0,offset:0,limit:20,hasMore:false,nextCursor:null});if(url.pathname===`${base}/posts/${postId}/replies`&&method==='POST'){const body=JSON.parse(String(init?.body));const reply={id:crypto.randomUUID(),postId,body:body.body,author:normal,createdAt:Date.now()};replies.push(reply);posts[0].replyCount=replies.length;return response({reply},201)}return response({error:'本地来源验收没有此接口'},501)};
function route(id:string|null){location.hash=id?`forum/post/${id}`:'forum'}
function Fixture(){const read=()=>/^#forum\/post\/(.+)$/.exec(location.hash)?.[1];const [id,setId]=useState(read);useEffect(()=>{const changed=()=>setId(read());window.addEventListener('hashchange',changed);return()=>window.removeEventListener('hashchange',changed)},[]);return <ForumView userId={account} isGuest={false} nickname={normal.nickname} postId={id} onPostChange={route} characters={[]} onCharacter={()=>{}} onRequireAccount={()=>{}}/>}
createRoot(document.getElementById('root')!).render(<Fixture/>);
